function charts(ls){let groups=['discovery','proposal','roadmap','payment','active','delivered'];let count=s=>ls.filter(l=>s==='active'?['active','onboarding'].includes(l.stage):s==='discovery'?['new','discovery'].includes(l.stage):l.stage===s).length,max=Math.max(1,...groups.map(count));let sources=[...new Set(ls.map(l=>l.source))];return `<div class="two dashcharts"><section class="card"><div class="eyebrow">client journey / live from sample records</div><h2>where work stands.</h2><div class="chartbars" role="img" aria-label="${E(groups.map(s=>s+': '+count(s)).join(', '))}">${groups.map(s=>`<div class="barline"><span>${s}</span><div><i style="width:${count(s)/max*100}%;background:${stageColors[s]}"></i></div><b>${count(s)}</b></div>`).join('')}</div></section><section class="card"><div class="eyebrow">enquiry sources</div><h2>where people find us.</h2>${sources.map(s=>`<div class="row"><span class="small">${E(s)}</span><b>${ls.filter(l=>l.source===s).length}</b></div>`).join('')||'<p>no enquiries in this workspace.</p>'}<span class="small">counts reflect the records visible in this workspace.</span></section></div>`}
overview=function(){let ls=scopedLeads(),open=(db.escalations||[]).filter(x=>x.status!=='resolved'&&(scope==='holding'||scope==='medialy'||x.venture===scope)),work=ls.flatMap(l=>l.work.filter(w=>scope==='holding'||w.venture===scope)),v=db.ventures.find(v=>v.name===scope);return title(scope==='holding'?'holding command centre':E(scope)+' / work & growth',scope==='holding'?'a clear view of the whole business.':'your venture. your priorities.',scope==='holding'?'connected clients, venture delivery and decisions that need attention.':scope==='medialy'?'shared crm for marketing, conversion and client follow-up, alongside medialy delivery.':'the same operating structure, focused on your venture’s clients and work.',button('+ capture enquiry','crm/new'))+`<div class="grid four">${[[ls.length,'client records'],[work.filter(w=>w.status!=='delivered').length,'open work items'],[open.length,'open escalations'],[ls.filter(l=>l.paid).length,'verified sample orders']].map(([n,t])=>`<div class="card"><span class="small">${t}</span><div class="metric">${n}</div></div>`).join('')}</div>${charts(ls)}<div class="two" style="margin:22px 0"><div class="card"><div class="eyebrow">your next action</div><h2>${v?'make the target actionable.':'turn the conversation into a clear next step.'}</h2><p>${v?E(v.target):'capture the enquiry, choose a relevant discovery route and publish the reviewed recommendation. the next action stays visible through delivery.'}</p><div class="actions">${button('open crm →','crm')}${button('review due actions','queue','secondary')}</div></div><div class="card"><div class="eyebrow">attention & escalation</div><h2>surface the blocker early.</h2><p>delays, missing requirements, complaints and approval requests need a named owner and response deadline.</p>${button('open escalation register →','escalations','secondary')}</div></div><div class="sectionhead"><h2>recent client records</h2></div>${leadTable(ls.slice(0,5))}`};
