const guidedGeneral={title:'find your next step',intro:'start with what matters to you. we will help put the situation into words before recommending any work.',qs:[Q('focus','what would you like help with today?','select',['turn an idea into a business','improve an existing business','solve an organisation or contractor need','get a specific service','i’m not sure yet']),Q('business','what name should we use for this business or idea?'),Q('offer','what do you do, or what would you like to offer?','textarea'),Q('customer','who would you most like to serve?','textarea'),Q('stage','which description feels closest to where you are?','select',['still exploring the idea','preparing to start','operating with occasional sales','operating with regular sales','managing a specific project']),Q('goal','if one thing improved first, what would you want it to be?','select',['a clearer business direction','more suitable customers','better conversion and follow-up','documents and business readiness','simpler operations and delivery','a capable team','help me work out the priority']),Q('friction','what is making that difficult right now?','textarea'),Q('assets','what is already working, or already in place?','textarea'),Q('vision','what would progress look like for you over the next 12 months?','textarea'),Q('pace','how would you prefer to move forward?','select',['show the priorities and costs first','start with a small practical step','build in stages','review a more complete solution'])]};
if(!db.guidedDiscoveryV2){let f=db.forms.find(f=>f.id==='general');f.title=guidedGeneral.title;f.intro=guidedGeneral.intro;f.qs=guidedGeneral.qs;f.published={...structuredClone(guidedGeneral),at:now()};db.guidedDiscoveryV2=true;save()}
function guidedHelp(q){if(/customer|serve/i.test(q.label))return ['the right audience makes the next steps clearer.','you can describe real customers or the people you hope to serve.'];if(/already|working|place/i.test(q.label))return ['we build from what you already have.','existing documents, brand assets, tools, skills and customer relationships may reduce what you need to buy.'];if(/improved|goal|progress|12 months/i.test(q.label))return ['a useful plan starts with your outcome.','choose the result that matters most to you. it is fine if the details are still taking shape.'];if(/difficult|friction/i.test(q.label))return ['we look for the obstacle before suggesting a solution.','describe what happens today, in your own words. a short example is enough.'];if(/prefer|forward/i.test(q.label))return ['you decide the pace.','your answer helps us present a suitable starting point. you can review recommendations without committing to a purchase.'];if(/name/i.test(q.label))return ['a working name is enough.','you do not need a registered name to explore an idea.'];return ['there is no perfect answer.','your answer helps us understand the situation. we will explain the recommendation and the cost before you choose any services.']}
function focusSkip(){formAnswers._skip=true;let el=document.getElementById('answer');if(el)el.value='not sure yet';document.getElementById('guided-question')?.requestSubmit()}
discoveryView=function(){let f=db.forms.find(f=>f.id===route[1]);if(!f)return notFound();let id=(route[2]||'new').split('?')[0],l=lead(id),pub=l?.discoverySnapshot||f.published||f,key=f.id+'/'+id;if(currentFormKey!==key){currentFormKey=key;formStep=0;formAnswers={...(l?.answers||{}),...JSON.parse(localStorage.getItem('hh-form-'+key)||'{}')}}let qs=pub.qs.filter(q=>!(q.id==='friction'&&formAnswers.focus==='get a specific service'));let q=qs[formStep];if(!q)return notFound();let value=formAnswers[q.id]||'',help=guidedHelp(q),last=formStep===qs.length-1;return `<div class="guidedwrap"><header class="guidednav"><a href="#home"><img class="logo" src="assets/${brandFor()?brandFor().name==='hamzury hub'?'hub':brandFor().name:'hamzury'}.png" alt="hamzury"></a><a href="https://desk.hamzury.com" target="_blank" rel="noopener">need a hand?</a></header><div class="guidedprogress"><span>your next step</span><span>${formStep+1} / ${qs.length}</span></div><div class="progress">${qs.map((_,i)=>`<i class="${i<=formStep?'done':''}"></i>`).join('')}</div><div class="guidedcontent"><div class="eyebrow">${['awareness','awareness','awareness','awareness','awareness','strategy','awareness','structure','success','strategy'][formStep]||'awareness'} / ${E(brandFor()?.name||'hamzury holding')}</div><form id="guided-question" onsubmit="guidedNext(event,'${f.id}','${id}')"><h1>${E(q.label)}</h1><p class="questionhint">${help[0]}</p>${q.type==='select'?`<fieldset class="answerchoices"><legend class="sr-only">${E(q.label)}</legend>${q.options.map((o,i)=>`<label class="answeroption ${value===o?'chosen':''}"><input type="radio" name="answer" value="${E(o)}" ${value===o?'checked':''} required onchange="this.closest('fieldset').querySelectorAll('label').forEach(l=>l.classList.remove('chosen'));this.parentElement.classList.add('chosen')"><span>${E(o)}</span><b aria-hidden="true">${String(i+1).padStart(2,'0')}</b></label>`).join('')}</fieldset>`:`<label class="sr-only" for="answer">your answer</label>${q.type==='textarea'?`<textarea id="answer" name="answer" placeholder="tell us in your own words…" required>${E(value)}</textarea>`:`<input id="answer" name="answer" value="${E(value)}" placeholder="a short answer is enough" required>`}`}${!l&&last?`<label for="returncontact">where can the team reach you? (sample reference only)</label><input id="returncontact" name="returncontact" required placeholder="sample email or whatsapp reference">`:''}<div class="guidedwhy"><span>why this matters</span><p>${help[1]}</p></div><div class="actions"><button>${last?'see my preliminary next step →':'continue →'}</button>${formStep?'<button type="button" class="ghost" onclick="formStep--;render()">back</button>':''}</div>${q.type!=='select'?'<button type="button" class="ghost small" onclick="focusSkip()">i’m not sure yet</button>':''}<p class="small">your answers stay in this browser during the demonstration. review the recommendation before deciding what to purchase.</p></form></div></div>`}
function guidedNext(e,fid,id){e.preventDefault();let f=db.forms.find(f=>f.id===fid),l=lead(id),pub=l?.discoverySnapshot||f.published||f,qs=pub.qs.filter(q=>!(q.id==='friction'&&formAnswers.focus==='get a specific service')),q=qs[formStep],d=new FormData(e.target);formAnswers[q.id]=d.get('answer');if(d.get('returncontact'))formAnswers._contact=d.get('returncontact');localStorage.setItem('hh-form-'+currentFormKey,JSON.stringify(formAnswers));if(formStep<qs.length-1){formStep++;render();window.scrollTo(0,0);return}if(!l)l=db.leads.find(x=>x.contact.trim().toLowerCase()===(formAnswers._contact||'').trim().toLowerCase());if(!l){let src=new URLSearchParams(location.hash.split('?')[1]||'').get('source')||'holding website';l={id:uid('HH'),name:formAnswers.business||formAnswers[pub.qs[0].id]||'new business enquiry',contact:formAnswers._contact,source:src,venture:db.ventures.find(v=>src===v.name+' website')?.name||'holding',scenario:fid,created:now(),proposal:'',proposalVersion:null,roadmapVersion:null,selected:[],paid:false,requirements:[],work:[],files:[],updates:[],events:[]};db.leads.unshift(l)}l.answers={...formAnswers};l.stage='discovery';l.next='team reviews the situation and prepares the itemized roadmap';l.proposalVersion=l.proposalVersion||{text:'thank you for explaining your situation. your focus is '+(formAnswers.goal||formAnswers.service||formAnswers.need||'the need you described')+'. we will check what already exists and clarify the priorities before recommending the work. your roadmap will explain the scope, cost and next action so you can choose how to proceed.',preliminary:true,version:1,at:now()};event(l,'guided discovery completed: '+f.title);go('client/'+l.id+'/proposal')}
function escalationsView(){let xs=(db.escalations||[]).filter(x=>scope==='holding'||scope==='medialy'||x.venture===scope);return title('client care / escalation register','the right issue, with the right owner.','raise a blocker, set a response time and record how it was resolved.')+`<div class="two"><form class="card" onsubmit="saveEscalation(event)"><h2>raise an escalation</h2><label>client record</label><select name="clientId"><option value="">general enquiry / not linked</option>${scopedLeads().map(l=>`<option value="${l.id}">${E(l.name)} / ${E(l.id)}</option>`).join('')}</select><div class="formgrid"><div><label>category</label><select name="category"><option>delivery delay</option><option>client complaint</option><option>missing requirements</option><option>payment clarification</option><option>quality review</option><option>approval needed</option><option>other</option></select></div><div><label>priority</label><select name="priority"><option>normal</option><option>high</option><option>urgent</option></select></div><div><label>responsible venture</label><select name="venture">${db.ventures.map(v=>`<option ${scope===v.name?'selected':''}>${E(v.name)}</option>`).join('')}</select></div><div><label>responsible person / role</label><input name="owner" required placeholder="who must respond?"></div></div><label>issue and requested outcome</label><textarea name="issue" required></textarea><label>response due</label><input type="datetime-local" name="due" required><div class="actions"><button>create escalation</button></div></form><section class="card"><h2>open and resolved issues</h2>${xs.map(x=>`<details open><summary><span class="priority ${x.priority}">${E(x.priority)}</span> ${E(x.category)} / ${E(x.status)}</summary><p>${E(x.issue)}</p><p class="small">owner: ${E(x.owner)} · ${E(x.venture)}<br>response due: ${displayDate(x.due)}<br>reference: ${E(x.clientId||'general enquiry')}</p><form onsubmit="resolveEscalation(event,'${x.id}')"><label>status</label><select name="status">${['open','in progress','waiting for client','resolved'].map(s=>`<option ${s===x.status?'selected':''}>${s}</option>`).join('')}</select><label>action taken / resolution</label><textarea name="resolution" required>${E(x.resolution||'')}</textarea><div class="actions"><button class="mini secondary">save decision</button></div></form></details>`).join('')||'<div class="empty">no escalations in this workspace. raise an issue when a real blocker needs attention.</div>'}</section></div>`}
function saveEscalation(e){e.preventDefault();let d=Object.fromEntries(new FormData(e.target)),x={...d,id:uid('ESC'),status:'open',created:now(),resolution:''};db.escalations=db.escalations||[];db.escalations.unshift(x);let l=lead(d.clientId);if(l)event(l,'escalation raised: '+d.category+' / owner '+d.owner);save();render();toast('escalation recorded. the live system will notify the assigned owner.')}
