function peopleView(){if(scope!=='holding')return note('people administration belongs to holding. venture needs can be escalated to the authorized holding team.');return title('people & venture activation','onboarding is a journey too.','start with the need. define the role, standards and supervised first result.')+`<div class="tabs">${peopleStages.map((s,i)=>`<button class="${wizardStep===i?'active':''}" onclick="wizardStep=${i};render()">${i+1}. ${s}</button>`).join('')}</div><div class="two"><form class="card" onsubmit="peopleNext(event)"><div class="eyebrow">step ${wizardStep+1} / ${peopleStages.length}</div><h2>${['what result needs an owner?','what arrangement fits the work?','make the expectations concrete.','prepare the invitation and assessment.','start with a supervised assignment.'][wizardStep]}</h2>${wizardStep===0?`<label>venture or holding unit</label><select name="venture"><option>holding</option>${db.ventures.map(v=>`<option ${staffDraft.venture===v.name?'selected':''}>${E(v.name)}</option>`).join('')}</select><label>problem, workload or opportunity</label><textarea name="need" required>${E(staffDraft.need||'')}</textarea><label>expected result</label><textarea name="result" required>${E(staffDraft.result||'')}</textarea>`:wizardStep===1?`<label>placement type</label><select name="type">${['staff','intern / siwes','supervised junior staff','project specialist','new venture / ceo activation'].map(s=>`<option ${staffDraft.type===s?'selected':''}>${s}</option>`).join('')}</select><label>skills and readiness needed</label><textarea name="skills" required>${E(staffDraft.skills||'')}</textarea><label>supervisor / accountable leader</label><input name="supervisor" value="${E(staffDraft.supervisor||'')}" required>`:wizardStep===2?`<label>role title</label><input name="title" value="${E(staffDraft.title||'')}" required><label>authority, limits and reporting</label><textarea name="authority" required>${E(staffDraft.authority||'')}</textarea><label>target and first deliverable</label><textarea name="first" required>${E(staffDraft.first||'')}</textarea>`:wizardStep===3?`<label>advert / invitation draft</label><textarea name="advert" required style="min-height:170px">${E(staffDraft.advert||'role: '+(staffDraft.title||'to confirm')+'\nventure: '+(staffDraft.venture||'holding')+'\nwork: '+(staffDraft.need||'')+'\nexpected result: '+(staffDraft.result||'')+'\nreadiness: '+(staffDraft.skills||'')+'\napplication route: confirm before publication.')}</textarea><label>practical assessment and review criteria</label><textarea name="assessment" required>${E(staffDraft.assessment||'')}</textarea><p class="small">this saves a draft. it does not publish a job advert or send invitations.</p>`:`<label>first-week assignment & acceptance standard</label><textarea name="activation" required>${E(staffDraft.activation||'')}</textarea><label>access, confidentiality and tool training checklist</label><textarea name="access" required>${E(staffDraft.access||'role access approved\nstandards acknowledged\ncalendar and reporting explained\nsupervised first task assigned\nreview date set')}</textarea><label>review date</label><input type="date" name="review" value="${E(staffDraft.review||'')}" required>`}<div class="actions"><button>${wizardStep===4?'save activation journey':'save & continue →'}</button>${wizardStep?'<button class="secondary" type="button" onclick="wizardStep--;render()">back</button>':''}</div></form><section class="card"><div class="eyebrow">the standard / assss</div><h2>each route has an sop.</h2><div class="statusline"><b>awareness</b><p>confirm the workload, skill gap and supervision capacity.</p></div><div class="statusline"><b>strategy</b><p>choose staff, internship, project support or venture activation.</p></div><div class="statusline"><b>structure</b><p>define role, authority, terms, owner and review criteria.</p></div><div class="statusline"><b>systems</b><p>activate access, practical training, calendar, tasks and reports.</p></div><div class="statusline"><b>success</b><p>review evidence of the first assignment and agree the next step.</p></div><p class="small">existing ceos receive updated system activation and assignments. their venture orientation is not repeated.</p></section></div><section class="card" style="margin-top:22px"><h2>saved activation journeys</h2>${(db.peopleJourneys||[]).map(p=>`<details><summary>${E(p.title||p.type)} / ${E(p.venture)}</summary>${Object.entries(p).filter(([k])=>!['id','created'].includes(k)).map(([k,v])=>`<p class="small"><b>${E(k)}:</b> ${E(v)}</p>`).join('')}</details>`).join('')||'<p>the completed journey, advert draft and activation checklist will be saved here.</p>'}</section>`}
