function resourceView(){let rs=(db.accessResources||[]).filter(r=>scope==='holding'||r.venture==='shared'||r.venture===scope);return title('documents & access directory','the right resource, easy to find.','keep templates, important records and approved login destinations together.')+`<div class="two"><section class="card"><h2>resource shelf</h2>${rs.map(r=>`<div class="row"><div><span class="eyebrow">${E(r.category)} / ${E(r.venture)}</span><h3>${E(r.title)}</h3><span class="small">${E(r.owner)}${r.username?' · '+E(r.username):''}</span><p class="small">${E(r.notes||'')}</p></div>${r.fileId?`<button class="mini secondary" onclick="downloadFile('${r.fileId}')">download</button>`:`<a class="button secondary mini" href="${E(r.url)}" target="_blank" rel="noopener">open ↗</a>`}</div>`).join('')||'<p>add a sample document or approved access link.</p>'}<div class="note">passwords and recovery codes belong in a dedicated password manager. this directory stores the vault item’s link and owner, never the secret itself.</div></section><form class="card" onsubmit="addResource(event)"><h2>add a reference</h2><label>category</label><select name="category"><option>document template</option><option>important document</option><option>login destination</option><option>password vault link</option><option>sop / checklist</option></select><label>title</label><input name="title" required><label>venture visibility</label><select name="venture"><option>shared</option><option>holding</option>${db.ventures.map(v=>`<option ${scope===v.name?'selected':''}>${E(v.name)}</option>`).join('')}</select><label>responsible owner</label><input name="owner" required><label>account label / email, optional</label><input name="username" placeholder="sample reference only"><label>https login or vault item link</label><input name="url" type="url" placeholder="https://"><label>or a sample document (up to 2 mb)</label><input type="file" name="file"><label>notes, no passwords or recovery codes</label><textarea name="notes"></textarea><div class="actions"><button>save resource reference</button></div><p class="small">demo documents stay in this browser. use test files only.</p></form></div>`}
async function addResource(e){e.preventDefault();let d=new FormData(e.target),r=Object.fromEntries([...d].filter(([k])=>k!=='file')),f=d.get('file');if(!f?.size&&!safeHttps(r.url)){toast('add a sample document or a valid https link');return}if(r.url&&!safeHttps(r.url)){toast('use a valid https destination');return}if(f?.size){if(f.size>2*1024*1024){toast('choose a sample file smaller than 2 mb');return}try{let idb=await filesDB,fid=uid('document');await new Promise((res,rej)=>{let tx=idb.transaction('files','readwrite');tx.objectStore('files').put(f,fid);tx.oncomplete=res;tx.onerror=rej});r.fileId=fid}catch{toast('local file storage is unavailable');return}}r.id=uid('resource');db.accessResources=db.accessResources||[];db.accessResources.unshift(r);save();render();toast('resource reference saved')}
function chatUI(){return `<div class="assistant-shell">${chatOpen?`<section class="assistant-panel" aria-label="hamzury guided assistant"><header><div><b>hamzury guide</b><span>guided assistant · demo</span></div><button aria-label="close assistant" onclick="chatOpen=false;drawChat()">×</button></header><div class="assistant-log" aria-live="polite"><div class="chatmessage">hello. i can help you find a starting point, check a sample project or reach the team.</div>${chatHistory.map(m=>`<div class="chatmessage ${m.user?'fromuser':''}">${E(m.text)}</div>`).join('')}</div><div class="chat-options"><button onclick="go('form/general/new');chatOpen=false;drawChat()">find my next step</button><button onclick="go('access');chatOpen=false;drawChat()">check my progress</button><button onclick="chatReply('escalation')">i need help with an issue</button><a href="https://desk.hamzury.com" target="_blank" rel="noopener">contact the desk ↗</a></div><form onsubmit="chatSubmit(event)"><label class="sr-only" for="chatmessage">your message to the guided assistant</label><input id="chatmessage" name="message" placeholder="what would you like help with?" required><button aria-label="send message">→</button></form><p class="chat-disclosure">guided responses, not a live agent. use sample information.</p></section>`:''}<button class="assistant-toggle" onclick="chatOpen=!chatOpen;drawChat()" aria-expanded="${chatOpen}">${chatOpen?'close':'ask hamzury'}</button></div>`}
function drawChat(){let x=document.getElementById('chatmount');if(!x){x=document.createElement('div');x.id='chatmount';document.body.append(x)}x.innerHTML=chatUI()}
function chatReply(topic){let text=topic==='escalation'?'tell the team your client reference, what happened and what result you need. use the contact desk for real support. in the workspace preview, open escalations to assign an owner and response deadline.':'choose find my next step for guided questions, or check my progress if you already have a client reference.';chatHistory.push({text});drawChat()}
function chatSubmit(e){e.preventDefault();let text=new FormData(e.target).get('message');chatHistory.push({user:true,text});let response=/complain|delay|issue|escal|refund|late|problem/i.test(text)?'i can help you reach the right place. for an existing order, include your client reference when contacting desk.hamzury.com. the workspace escalation register records the issue, owner, response date and resolution.':/id|track|progress|status|deliver/i.test(text)?'choose check my progress and enter your client reference. your roadmap shows requirements, active work, released files and your next action.':/price|cost|pay|quote/i.test(text)?'prices belong to the selected scope. your roadmap shows confirmed catalogue prices or price to confirm. review the quotation and terms before you choose to pay.':/document|cac|tax|scuml/i.test(text)?'bizdoc discovery helps clarify the document need before processing. open our expertise from the homepage, choose bizdoc and follow the relevant questions.':/staff|intern|ceo|onboard/i.test(text)?'holding’s people & onboarding workspace starts with the need, then the placement route, role standard, invitation draft and supervised first assignment.':'start with find my next step. the questions help clarify your situation and priorities, then your team reviews the recommendation. you choose whether to proceed.';chatHistory.push({text:response});drawChat()}
const previousAccess=access;
access=function(){return previousAccess().replaceAll('HH-DEMO-001','HH-JOURNEY-001').replace('open your sample project.','check your work and results.').replace('continue →','check my progress →')};
const prevUXRender=render;
render=function(){route=location.hash.slice(1).split('/');let p=route[0]||'home';if(p==='escalations')root.innerHTML=demo()+workspace(escalationsView());else if(p==='people')root.innerHTML=demo()+workspace(peopleView());else if(p==='resources-admin')root.innerHTML=demo()+workspace(resourceView());else prevUXRender();let v=brandFor();if(!['home','form','client','about','hm','portfolio','voices','resources','access','expertise','venture-page'].includes(p)&&scope!=='holding')v=db.ventures.find(v=>v.name===scope);if(v){document.documentElement.style.setProperty('--choc',v.color);document.documentElement.style.setProperty('--milk','#f6f8fa')}else{document.documentElement.style.setProperty('--choc','#3b241a');document.documentElement.style.setProperty('--milk','#f8f3eb')}attachLabels();drawChat()};
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&chatOpen){chatOpen=false;drawChat()}});render();
const prevQueue=queueView;
queueView=function(){let ls=db.leads,html;try{db.leads=ls.filter(inScope);html=prevQueue()}finally{db.leads=ls}let overdue=(db.escalations||[]).filter(x=>x.status!=='resolved'&&new Date(x.due)<new Date()&&(scope==='holding'||scope==='medialy'||x.venture===scope));return html+`<section class="card" style="margin-top:22px"><h2>escalation responses due</h2>${overdue.map(x=>`<div class="row"><div><span class="priority ${x.priority}">${E(x.priority)}</span><h3>${E(x.category)}</h3><span class="small">${E(x.owner)} · ${displayDate(x.due)}</span></div>${button('review escalation','escalations','secondary mini')}</div>`).join('')||'<p>no overdue escalation responses in this view.</p>'}</section>`};
function routineView(){let ls=scopedLeads(),work=ls.flatMap(l=>l.work.filter(w=>scope==='holding'||w.venture===scope).map(w=>({l,w})));return title('calendar / tasks / standards','know what to do, and when.','the shared holding rhythm, with work and accountability focused on this workspace.')+`<div class="two"><section class="card"><h2>the operating rhythm</h2>${[['daily','08:00–08:30','individual priorities and checklist'],['monday','target & plan windows','receive targets, translate them into assignments and submit weekly plans'],['tuesday','time to confirm','systems and skills training tied to the target'],['wednesday','11:00 solitude / research','research new developments, tools and implementation opportunities'],['thursday','five minutes per presentation','explain the learning, cost, feasibility and next action'],['friday','review time to confirm','verified results, venture reports and team culture']].map(([d,t,p])=>`<div class="row"><div><h3>${d}</h3><span class="small">${t}</span><p class="small">${p}</p></div></div>`).join('')}<p class="small">08:00–17:00 · africa/lagos. programme timetables remain separate. unresolved meeting overlaps and times require holding approval.</p></section><section class="card"><h2>work assigned to this workspace</h2>${work.map(({l,w})=>`<div class="row"><div>${tag(w.venture)}<h3>${E(w.title)}</h3><span class="small">${E(w.owner)} · ${E(w.status)}<br>due: ${displayDate(w.due)}</span></div>${button('open work','lead/'+l.id+'/delivery','secondary mini')}</div>`).join('')||'<p>no activated client work in this workspace yet.</p>'}<div class="note">every assignment has an owner, deadline, acceptance standard, evidence and reviewer. a submission closes only after the result is approved.</div><h3>daily closeout</h3><form onsubmit="saveRoutine(event)"><label>completed result and evidence</label><textarea name="result" required></textarea><label>blocker, next action and owner</label><textarea name="next" required></textarea><div class="actions"><button>submit daily record</button></div></form></section></div><section class="card" style="margin-top:22px"><h2>recent workspace records</h2>${(db.routineReports||[]).filter(r=>scope==='holding'||r.scope===scope).slice(0,8).map(r=>`<div class="statusline"><span class="small">${E(r.scope)} · ${displayDate(r.at)}</span><p>${E(r.result)}</p><p class="small">next: ${E(r.next)}</p></div>`).join('')||'<p>submitted daily records appear here.</p>'}</section>`}
function saveRoutine(e){e.preventDefault();db.routineReports=db.routineReports||[];db.routineReports.unshift({...Object.fromEntries(new FormData(e.target)),scope,at:now()});save();render();toast('daily workspace record saved')}
const beforeRoutineRender=render;
render=function(){route=location.hash.slice(1).split('/');if(route[0]==='routine'){root.innerHTML=demo()+workspace(routineView());let v=db.ventures.find(v=>v.name===scope);document.documentElement.style.setProperty('--choc',v?.color||'#3b241a');attachLabels();drawChat()}else beforeRoutineRender()};
const beforePlacement=peopleView;
peopleView=function(){let html=beforePlacement(),t=staffDraft.type;if(!t)return html;let sop=t==='intern / siwes'?'intern / siwes: confirm the placement terms, learning goals, five-day work schedule, named supervisor and daily evidence. assign work according to readiness.':t==='supervised junior staff'?'junior staff: use supervised assignments, readiness checks and updates. the innovator-to-ceo route requires three weeks of junior staff experience. hub retains programme administration.':t==='new venture / ceo activation'?'venture activation: confirm mandate, monthly target, authority, services, team plan, reporting and system access. existing ceos move directly into execution without repeated venture orientation.':t==='project specialist'?'project specialist: agree scope, deliverables, fee, confidentiality, access limits, reviewer and handover before work starts.':'staff: agree role, terms, authority, targets, access and reporting. complete practical system training and review the first supervised result.';return html+note(sop)};
render();
const fullCatalogue=catalogue;
catalogue=function(){if(scope==='holding')return fullCatalogue();let services=db.services,ventures=db.ventures;try{db.services=services.filter(s=>s.v===scope);db.ventures=ventures.filter(v=>v.name===scope);if(route[1]==='edit'&&route[2]!=='new'&&!db.services.some(s=>s.id===route[2]))return note('this catalogue item belongs to another venture.');return fullCatalogue()}finally{db.services=services;db.ventures=ventures}};
const fullNewLead=newLead;
newLead=function(){let html=fullNewLead();if(scope!=='holding')html=html.replace(`<option>${E(scope)}</option>`,`<option selected>${E(scope)}</option>`);return html};
render();
